do $$begin begin perform public.pos_checkout(gen_random_uuid(),'cccccccc-cccc-4ccc-8ccc-cccccccccccc','[{"id":"aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa","qty":1}]','Tunai',10000,'');raise exception 'TEST_FAILED';exception when others then if sqlerrm='TEST_FAILED' then raise;end if;end;end $$;
