set local role authenticated;
select public.pos_snapshot()->'me'->>'role' as authenticated_rpc_role;
do $$begin begin perform 1 from public.products;raise exception 'TEST_FAILED';exception when insufficient_privilege then null;end;end $$;
reset role;insert into test_results values('authenticated direct table reads blocked','PASS');
